1	/* TikTok product manage list scraper - calibrated 2026-07-31 seller-uk. */
2	(function () {
3	  function cleanText(t) {
4	    return String(t == null ? '' : t).replace(/\s+/g, ' ').trim();
5	  }
6	  function detectCurrency(text) {
7	    var s = String(text == null ? '' : text);
8	    if (/[£]|GBP/i.test(s)) return 'GBP';
9	    if (/[€]|EUR/i.test(s)) return 'EUR';
10	    if (/[¥￥]|CNY|RMB/i.test(s) && !/\$/.test(s)) return 'CNY';
11	    if (/\$|USD/i.test(s)) return 'USD';
12	    return null;
13	  }
14	  function parseNumber(value) {
15	    if (value == null || value === '') return null;
16	    if (typeof value === 'number' && isFinite(value)) return value;
17	    var s = String(value).trim();
18	    if (!s || s === '-' || s === '—') return null;
19	    s = s.replace(/[,\s]/g, '').replace(/[¥$€£￥]/g, '');
20	    s = s.replace(/USD|GBP|EUR|CNY|RMB/gi, '').replace(/%/g, '');
21	    var n = Number(s);
22	    return isFinite(n) ? n : null;
23	  }
24	  function extractProductId(text) {
25	    var s = cleanText(text);
26	    var m = s.match(/ID\s*[:：]\s*(\d{10,22})/i) || s.match(/\b(17\d{15,20})\b/) || s.match(/\b(\d{15,22})\b/);
27	    return m ? m[1] : '';
28	  }
29	  function extractSellerSku(text) {
30	    var s = cleanText(text);
31	    var m = s.match(/(?:商家\s*)?SKU\s*[:：]\s*([^\s]+)/i);
32	    return m ? m[1] : '';
33	  }
34	  function extractSalesQty(text) {
35	    var s = cleanText(text);
36	    var m = s.match(/已售出\s*(\d+)/) || s.match(/Sold\s*(\d+)/i);
37	    return m ? Number(m[1]) : null;
38	  }
39	  function extractProductName(text) {
40	    var s = cleanText(text);
41	    s = s.replace(/ID\s*[:：]\s*\d{10,22}/ig, ' ');
42	    s = s.replace(/(?:商家\s*)?SKU\s*[:：]\s*\S+/ig, ' ');
43	    return s.replace(/\s+/g, ' ').trim();
44	  }
45	  var HEADER_ALIASES = {
46	    product: ['商品', '商品名称', '产品名称', 'product', 'product name', 'title'],
47	    performance: ['表现', 'performance'],
48	    status: ['状态', '商品状态', 'status'],
49	    stockQty: ['库存', '可售库存', 'stock'],
50	    price: ['零售价', '价格', '售价', 'price', 'retail']
51	  };
52	  function matchField(header) {
53	    var h = cleanText(header).toLowerCase();
54	    if (!h) return null;
55	    var best = null, bestLen = 0;
56	    var keys = Object.keys(HEADER_ALIASES);
57	    for (var i = 0; i < keys.length; i++) {
58	      var field = keys[i];
59	      var aliases = HEADER_ALIASES[field];
60	      for (var j = 0; j < aliases.length; j++) {
61	        var al = aliases[j].toLowerCase();
62	        if (h === al || h.indexOf(al) >= 0) {
63	          if (al.length >= bestLen) { best = field; bestLen = al.length; }
64	        }
65	      }
66	    }
67	    return best;
68	  }
69	  function scoreTable(table) {
70	    var trs = Array.prototype.slice.call(table.querySelectorAll('tr'));
71	    if (trs.length < 2) return 0;
72	    var head = Array.prototype.slice.call(trs[0].querySelectorAll('th,td')).map(function (c) { return cleanText(c.textContent); });
73	    var hits = 0, fields = {};
74	    for (var i = 0; i < head.length; i++) {
75	      var f = matchField(head[i]);
76	      if (f) { hits++; fields[f] = true; }
77	    }
78	    if (!fields.product && !fields.stockQty && !fields.price) {
79	      var idHits = 0;
80	      for (var r = 1; r < Math.min(trs.length, 6); r++) {
81	        if (extractProductId(trs[r].textContent || '')) idHits++;
82	      }
83	      if (idHits === 0) return 0;
84	      return idHits * 5 + trs.length;
85	    }
86	    return hits * 10 + Math.min(trs.length, 80);
87	  }
88	  function pickBestTable() {
89	    var tables = Array.prototype.slice.call(document.querySelectorAll('table'));
90	    var best = null, bestScore = 0;
91	    for (var i = 0; i < tables.length; i++) {
92	      var s = scoreTable(tables[i]);
93	      if (s > bestScore) { bestScore = s; best = tables[i]; }
94	    }
95	    return bestScore >= 8 ? best : null;
96	  }
97	  function defaultColMap() {
98	    return { product: 1, performance: 2, status: 3, stockQty: 4, price: 5 };
99	  }
100	  function parseHtmlTable(table) {
101	    var trs = Array.prototype.slice.call(table.querySelectorAll('tr'));
102	    if (trs.length < 2) return { rows: [], headers: [], colMap: {} };
103	    var headIdx = -1;
104	    for (var i = 0; i < Math.min(3, trs.length); i++) {
105	      var cells = Array.prototype.slice.call(trs[i].querySelectorAll('th,td')).map(function (c) { return cleanText(c.textContent); });
106	      var hits = 0, hasPid = false;
107	      for (var h = 0; h < cells.length; h++) {
108	        if (matchField(cells[h])) hits++;
109	        if (extractProductId(cells[h])) hasPid = true;
110	      }
111	      if (hits >= 2 && !hasPid) { headIdx = i; break; }
112	    }
113	    var colMap = {}, headCells = [];
114	    if (headIdx >= 0) {
115	      headCells = Array.prototype.slice.call(trs[headIdx].querySelectorAll('th,td')).map(function (c) { return cleanText(c.textContent); });
116	      headCells.forEach(function (h, idx) {
117	        var f = matchField(h);
118	        if (f && colMap[f] == null) colMap[f] = idx;
119	      });
120	    }
121	    var def = defaultColMap();
122	    Object.keys(def).forEach(function (k) { if (colMap[k] == null) colMap[k] = def[k]; });
123	    if (!headCells.length) headCells = ['', 'product', 'perf', 'status', 'stock', 'price'];
124	    var rows = [], seen = {};
125	    var start = headIdx >= 0 ? headIdx + 1 : 0;
126	    for (var r = start; r < trs.length; r++) {
127	      var tds = Array.prototype.slice.call(trs[r].querySelectorAll('td,th'));
128	      if (!tds.length) continue;
129	      var vals = tds.map(function (c) { return cleanText(c.textContent); });
130	      function get(f) { return colMap[f] != null ? vals[colMap[f]] || '' : ''; }
131	      var productCell = get('product') || vals.join(' ');
132	      var productId = extractProductId(productCell) || extractProductId(vals.join(' '));
133	      var sellerSku = extractSellerSku(productCell);
134	      var productName = extractProductName(productCell);
135	      if (!productId) {
136	        if (sellerSku) productId = 'sku:' + sellerSku;
137	        else if (productName) productId = 'name:' + productName.slice(0, 80);
138	      }
139	      if (!productId || seen[productId]) continue;
140	      seen[productId] = true;
141	      var perf = get('performance');
142	      rows.push({
143	        productId: productId,
144	        productName: productName,
145	        sellerSku: sellerSku,
146	        status: get('status'),
147	        stockQty: parseNumber(get('stockQty')),
148	        price: parseNumber(get('price')),
149	        salesQty: extractSalesQty(perf),
150	        currencyHint: detectCurrency(vals.join(' ')) || detectCurrency(get('price')),
151	        rawCells: vals.slice(0, 10)
152	      });
153	    }
154	    return { rows: rows, headers: headCells, colMap: colMap };
155	  }
156	  function parseIdBlocks() {
157	    var nodes = Array.prototype.slice.call(document.querySelectorAll('div,tr,li,section'));
158	    var rows = [], seen = {};
159	    for (var i = 0; i < nodes.length; i++) {
160	      var text = cleanText(nodes[i].textContent).slice(0, 500);
161	      if (text.indexOf('ID:') < 0 && text.indexOf('ID：') < 0) continue;
162	      if (text.length > 450) continue;
163	      var productId = extractProductId(text);
164	      if (!productId || seen[productId]) continue;
165	      seen[productId] = true;
166	      var pm = text.match(/[£$€]\s*[0-9.]+/);
167	      rows.push({
168	        productId: productId,
169	        productName: extractProductName(text),
170	        sellerSku: extractSellerSku(text),
171	        status: '',
172	        stockQty: null,
173	        price: pm ? parseNumber(pm[0]) : null,
174	        salesQty: extractSalesQty(text),
175	        currencyHint: detectCurrency(text),
176	        rawCells: [text.slice(0, 160)]
177	      });
178	    }
179	    return rows.length ? { rows: rows, headers: ['id-blocks'], colMap: {}, source: 'id-blocks' } : null;
180	  }
181	  try {
182	    var url = location.href || '';
183	    var title = document.title || '';
184	    var table = pickBestTable();
185	    var parsed = null, source = 'none';
186	    if (table) { parsed = parseHtmlTable(table); source = 'html-table'; }
187	    if (!parsed || !parsed.rows || parsed.rows.length === 0) {
188	      var fb = parseIdBlocks();
189	      if (fb) { parsed = fb; source = fb.source || 'id-blocks'; }
190	    }
191	    var rows = parsed && parsed.rows ? parsed.rows : [];
192	    var currencyHits = { USD: 0, GBP: 0, EUR: 0, CNY: 0 };
193	    for (var ri = 0; ri < rows.length; ri++) {
194	      var c = rows[ri].currencyHint;
195	      if (c && currencyHits[c] != null) currencyHits[c]++;
196	    }
197	    var currency = 'GBP', max = -1;
198	    var ks = Object.keys(currencyHits);
199	    for (var k = 0; k < ks.length; k++) {
200	      if (currencyHits[ks[k]] > max) { max = currencyHits[ks[k]]; currency = ks[k]; }
201	    }
202	    if (max <= 0) currency = 'GBP';
203	    var ok = rows.length > 0;
204	    return JSON.stringify({
205	      ok: ok, source: source, module: 'products', url: url, title: title,
206	      currency: currency, currencyHits: currencyHits,
207	      headers: parsed && parsed.headers ? parsed.headers : [],
208	      colMap: parsed && parsed.colMap ? parsed.colMap : {},
209	      rows: rows, rowCount: rows.length,
210	      error: ok ? null : 'no product table. url=' + url
211	    });
212	  } catch (e) {
213	    return JSON.stringify({ ok: false, source: 'none', module: 'products', url: location.href || '', rows: [], error: String(e && e.message ? e.message : e) });
214	  }
