1	# Qingquan center ingest client (Stage A dual-write)
2	# Dot-sourced by run-multi-store.ps1; can also be used alone.
3	#
4	# config.qingquan example:
5	# {
6	#   "enabled": true,
7	#   "baseUrl": "https://qingquan.jmzlai.com",
8	#   "apiKey": "<must match server INGEST_DEFAULT_API_KEY>",
9	#   "source": "tiktok_ads",
10	#   "failOpen": true,
11	#   "timeoutSec": 30
12	# }
13	#
14	# PS 5.1 pitfalls:
15	# - @($hashtable) enumerates KEYS, not a single-element array
16	# - return ,$object[] may still unwrap a single element on assignment
17	# - Generic type literals like List[object] break the parser
18	# Keep items in ArrayList; serialize via JavaScriptSerializer.
19	
20	function Get-QingquanConfig($cfg) {
21	  if (-not $cfg.qingquan) {
22	    return [pscustomobject]@{
23	      enabled    = $false
24	      baseUrl    = 'http://127.0.0.1:8000'
25	      apiKey     = ''
26	      source     = 'tiktok_ads'
27	      failOpen   = $true
28	      timeoutSec = 30
29	    }
30	  }
31	  $q = $cfg.qingquan
32	  $enabled = $false
33	  if ($null -ne $q.enabled) { $enabled = [bool]$q.enabled }
34	  $failOpen = $true
35	  if ($null -ne $q.failOpen) { $failOpen = [bool]$q.failOpen }
36	  $timeout = 30
37	  if ($null -ne $q.timeoutSec) { $timeout = [int]$q.timeoutSec }
38	  $source = 'tiktok_ads'
39	  if ($q.source) { $source = [string]$q.source }
40	  $base = 'http://127.0.0.1:8000'
41	  if ($q.baseUrl) { $base = [string]$q.baseUrl }
42	  $key = ''
43	  if ($q.apiKey) { $key = [string]$q.apiKey }
44	  return [pscustomobject]@{
45	    enabled    = $enabled
46	    baseUrl    = $base.TrimEnd('/')
47	    apiKey     = $key
48	    source     = $source
49	    failOpen   = $failOpen
50	    timeoutSec = $timeout
51	  }
52	}
53	
54	function Get-FeishuWriteMode($cfg) {
55	  # direct | dual | center
56	  $mode = 'direct'
57	  if ($cfg.feishu -and $cfg.feishu.writeMode) {
58	    $mode = [string]$cfg.feishu.writeMode
59	  } elseif ($cfg.qingquan -and $cfg.qingquan.enabled) {
60	    $mode = 'dual'
61	  }
62	  $mode = $mode.ToLowerInvariant()
63	  if ($mode -notin @('direct', 'dual', 'center')) { $mode = 'direct' }
64	  return $mode
65	}
66	
67	function Get-QingquanItemList {
68	  param($Items)
69	  $list = New-Object System.Collections.ArrayList
70	  if ($null -eq $Items) { return $list }
71	
72	  if ($Items -is [System.Collections.ArrayList]) {
73	    foreach ($x in $Items) {
74	      if ($null -ne $x) { [void]$list.Add($x) }
75	    }
76	    return $list
77	  }
78	
79	  # Single Hashtable / Dictionary = one ingest item (do NOT @()-enumerate keys)
80	  if ($Items -is [System.Collections.IDictionary]) {
81	    [void]$list.Add($Items)
82	    return $list
83	  }
84	
85	  if ($Items -is [System.Array]) {
86	    foreach ($x in $Items) {
87	      if ($null -eq $x) { continue }
88	      [void]$list.Add($x)
89	    }
90	    return $list
91	  }
92	
93	  # Other enumerables (but not string)
94	  $isEnum = $false
95	  try {
96	    if (($Items -is [System.Collections.IEnumerable]) -and -not ($Items -is [string])) {
97	      $isEnum = $true
98	    }
99	  } catch { $isEnum = $false }
100	
101	  if ($isEnum) {
102	    foreach ($x in $Items) {
103	      if ($null -ne $x) { [void]$list.Add($x) }
104	    }
105	    return $list
106	  }
107	
108	  [void]$list.Add($Items)
109	  return $list
110	}
111	
112	function ConvertTo-QingquanIngestItems {
113	  param(
114	    [Parameter(Mandatory = $true)] $Rows,
115	    [Parameter(Mandatory = $true)] [string]$CollectedAt,
116	    [string]$Currency = 'USD'
117	  )
118	  if ([string]::IsNullOrWhiteSpace($Currency)) { $Currency = 'USD' }
119	  $items = New-Object System.Collections.ArrayList
120	  foreach ($r in @($Rows)) {
121	    $campaign = [string]$r.campaign
122	    if (-not $campaign) { continue }
123	    $storeId = [string]$r.storeId
124	    $bizDate = [string]$r.date
125	    $spend = 0; if ($null -ne $r.spend) { $spend = [double]$r.spend }
126	    $orders = 0; if ($null -ne $r.orders) { $orders = [double]$r.orders }
127	    $roi = $null; if ($null -ne $r.roi) { $roi = [double]$r.roi }
128	    $revenue = 0; if ($null -ne $r.revenue) { $revenue = [double]$r.revenue }
129	    $dailyBudget = $null
130	    if ($null -ne $r.dailyBudget -and "$($r.dailyBudget)" -ne '') { $dailyBudget = [double]$r.dailyBudget }
131	    $targetRoi = $null
132	    if ($null -ne $r.targetRoi -and "$($r.targetRoi)" -ne '') { $targetRoi = [double]$r.targetRoi }
133	    $netCost = $null
134	    if ($null -ne $r.netCost -and "$($r.netCost)" -ne '') { $netCost = [double]$r.netCost }
135	    $avgOrderCost = $null
136	    if ($null -ne $r.avgOrderCost -and "$($r.avgOrderCost)" -ne '') { $avgOrderCost = [double]$r.avgOrderCost }
137	    $status = 'success'; if ($r.status) { $status = [string]$r.status }
138	    $planStatus = ''; if ($r.planStatus) { $planStatus = [string]$r.planStatus }
139	    $deliveryStatus = ''; if ($r.deliveryStatus) { $deliveryStatus = [string]$r.deliveryStatus }
140	    $sourceUrl = ''; if ($r.sourceUrl) { $sourceUrl = [string]$r.sourceUrl }
141	    $storeName = ''; if ($r.store) { $storeName = [string]$r.store }
142	    $rowCurrency = $Currency
143	    if ($r.currency) { $rowCurrency = [string]$r.currency }
144	
145	    $payload = @{
146	      campaign_name   = $campaign
147	      spend           = $spend
148	      orders          = $orders
149	      roi             = $roi
150	      revenue         = $revenue
151	      daily_budget    = $dailyBudget
152	      target_roi      = $targetRoi
153	      net_cost        = $netCost
154	      avg_order_cost  = $avgOrderCost
155	      delivery_status = $deliveryStatus
156	      row_status      = $status
157	      plan_status     = $planStatus
158	      currency        = $rowCurrency
159	      source_url      = $sourceUrl
160	    }
161	
162	    [void]$items.Add(@{
163	      platform        = 'tiktok'
164	      shop_id         = $storeId
165	      shop_name       = $storeName
166	      biz_date        = $bizDate
167	      collected_at    = $CollectedAt
168	      idempotency_key = ("tiktok_ads:{0}:{1}:{2}" -f $storeId, $campaign, $bizDate)
169	      payload         = $payload
170	      evidence        = @{ source_url = $sourceUrl }
171	    })
172	  }
173	  # PS 5.1 unwraps a 1-element ArrayList into the bare Hashtable on `return`.
174	  # -NoEnumerate keeps the list intact so .Count == item count (not key count).
175	  Write-Output -NoEnumerate $items
176	}
177	
178	function ConvertTo-QingquanOrderIngestItems {
179	  param(
180	    [Parameter(Mandatory = $true)] $Rows,
181	    [Parameter(Mandatory = $true)] [string]$CollectedAt,
182	    [Parameter(Mandatory = $true)] [string]$StoreId,
183	    [string]$StoreName = '',
184	    [string]$BizDate = '',
185	    [string]$Currency = 'USD',
186	    [string]$SourceUrl = ''
187	  )
188	  if ([string]::IsNullOrWhiteSpace($Currency)) { $Currency = 'USD' }
189	  $items = New-Object System.Collections.ArrayList
190	  foreach ($r in @($Rows)) {
191	    $orderId = ''
192	    if ($r.orderId) { $orderId = [string]$r.orderId }
193	    elseif ($r.order_id) { $orderId = [string]$r.order_id }
194	    if (-not $orderId) { continue }
195	
196	    $qty = 0
197	    if ($null -ne $r.quantity) { try { $qty = [double]$r.quantity } catch { $qty = 0 } }
198	    $pay = 0
199	    if ($null -ne $r.payAmount) { try { $pay = [double]$r.payAmount } catch { $pay = 0 } }
200	    elseif ($null -ne $r.pay_amount) { try { $pay = [double]$r.pay_amount } catch { $pay = 0 } }
201	
202	    $rowCurrency = $Currency
203	    if ($r.currency) { $rowCurrency = [string]$r.currency }
