function extractRelativeTime(text) {
    var s = cleanText(text);
    // strip leading order id so "5769...3 分钟前" -> "3 分钟前"
    s = s.replace(/\b57\d{16}\b/g, ' ').replace(/\b\d{15,20}\b/g, ' ');
    s = s.replace(/\s+/g, ' ').trim();
    var m =
      s.match(/(\d+\s*分钟前)/) ||
      s.match(/(今天\s*\d{1,2}:\d{2}(?::\d{2})?)/) ||
      s.match(/(\d{4}\/\d{1,2}\/\d{1,2}\s*\d{1,2}:\d{2}(?::\d{2})?)/) ||
      s.match(/(\d+\s*小时前|\d+\s*天前)/);
    return m ? m[1] : '';
  }

