function ConvertTo-QingquanIngestJson {
  param([Parameter(Mandatory = $true)] $Items)
  $list = Get-QingquanItemList $Items
  if ($list.Count -eq 0) {
    throw 'qingquan payload has 0 items'
  }

  try {
    Add-Type -AssemblyName System.Web.Extensions -ErrorAction Stop
    $ser = New-Object System.Web.Script.Serialization.JavaScriptSerializer
    $ser.MaxJsonLength = 50MB
    $payload = New-Object 'System.Collections.Generic.Dictionary[string,object]'
    $payload['items'] = $list.ToArray()
    $json = $ser.Serialize($payload)
  } catch {
    $parts = New-Object System.Collections.ArrayList
    foreach ($it in $list) {
      $piece = ($it | ConvertTo-Json -Depth 12 -Compress)
      [void]$parts.Add($piece)
    }
    $json = '{"items":[' + ($parts -join ',') + ']}'
  }

  if ([string]::IsNullOrWhiteSpace($json) -or $json -notmatch '"items"\s*:\s*\[') {
    $preview = ''
    if ($json) { $preview = $json.Substring(0, [Math]::Min(120, $json.Length)) }
    $len = 0
    if ($json) { $len = $json.Length }
    throw ("qingquan payload json invalid (len={0}): {1}" -f $len, $preview)
  }
  if ($json -match '"items"\s*:\s*\[\s*\]') {
    throw 'qingquan payload items array is empty after serialize'
  }
  return $json
}

function Send-QingquanIngest {
  param(
    [Parameter(Mandatory = $true)] $Config,
    [Parameter(Mandatory = $true)] $Items,
    [string]$Source = '',
    [switch]$Quiet
  )
  $q = Get-QingquanConfig $Config
  if (-not $q.enabled) {
    return [pscustomobject]@{ ok = $true; skipped = $true; reason = 'qingquan.disabled'; accepted = 0; duplicated = 0; failed = 0 }
  }
  if (-not $q.apiKey) {
    $msg = 'qingquan.apiKey empty'
    if ($q.failOpen) {
      if (-not $Quiet) { Write-Warning $msg }
      return [pscustomobject]@{ ok = $false; skipped = $false; error = $msg; accepted = 0; duplicated = 0; failed = 0 }
    }
    throw $msg
  }

  $itemList = Get-QingquanItemList $Items
  if ($itemList.Count -eq 0) {
    return [pscustomobject]@{ ok = $true; skipped = $true; reason = 'empty-items'; accepted = 0; duplicated = 0; failed = 0 }
  }

  $useSource = $q.source
  if (-not [string]::IsNullOrWhiteSpace($Source)) { $useSource = $Source.Trim() }
  $url = "{0}/api/v1/ingest/{1}" -f $q.baseUrl, $useSource
  try {
    $json = ConvertTo-QingquanIngestJson -Items $itemList
  } catch {
    $msg = [string]$_
    if ($q.failOpen) {
      if (-not $Quiet) { Write-Warning $msg }
      return [pscustomobject]@{ ok = $false; skipped = $false; error = $msg; accepted = 0; duplicated = 0; failed = $itemList.Count }

# TikTok products multi-store scrape (P2b skeleton) via ziniao-cli
# Usage:
#   powershell -ExecutionPolicy Bypass -File .\scripts\run-products.ps1
#   powershell -ExecutionPolicy Bypass -File .\scripts\run-products.ps1 -ListOnly
#   powershell -ExecutionPolicy Bypass -File .\scripts\run-products.ps1 -DryRun true
#
# Requires: Ziniao client + Bridge; config\stores.config.json
# Does NOT write Feishu by default (products Feishu optional later) — only Qingquan ingest.

param(
  [string]$ConfigPath = "",
  [switch]$ListOnly,
  [string]$DryRun = ""
)

$ErrorActionPreference = 'Stop'
$PSNativeCommandUseErrorActionPreference = $false
$root = Split-Path $PSScriptRoot -Parent
if (-not $ConfigPath) { $ConfigPath = Join-Path $root 'config\stores.config.json' }
$scrapeJsPath = Join-Path $root 'scripts\scrape-products-page.js'
$clickNextJsPath = Join-Path $root 'scripts\products-click-next.js'
if (-not (Test-Path $ConfigPath)) { throw "Missing config: $ConfigPath" }
if (-not (Test-Path $scrapeJsPath)) { throw "Missing $scrapeJsPath" }
$clickNextJs = ''
if (Test-Path $clickNextJsPath) { $clickNextJs = Get-Content $clickNextJsPath -Raw -Encoding UTF8 }

$cfg = Get-Content $ConfigPath -Raw -Encoding UTF8 | ConvertFrom-Json
$scrapeJs = Get-Content $scrapeJsPath -Raw -Encoding UTF8
$qingquanLib = Join-Path $PSScriptRoot 'qingquan-client.ps1'
if (Test-Path $qingquanLib) { . $qingquanLib }

$script:logsDir = Join-Path $root 'logs'
New-Item -ItemType Directory -Force -Path $script:logsDir | Out-Null
$script:runStamp = Get-Date -Format 'yyyyMMdd-HHmmss'
$script:runLogFile = Join-Path $script:logsDir ("products-run-{0}.log" -f $script:runStamp)

function Write-RunLog([string]$msg) {
  $line = "[{0}] {1}" -f (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'), $msg
  try { Add-Content -LiteralPath $script:runLogFile -Value $line -Encoding UTF8 } catch { }
}
function Write-Step([string]$msg) {
  Write-Host ("[{0}] {1}" -f (Get-Date -Format 'HH:mm:ss'), $msg)
  Write-RunLog $msg
}

function ConvertTo-ProcessArgument([string]$s) {
  if ($null -eq $s) { return '""' }
  if ($s -match '[\s"]') { return '"' + ($s -replace '"', '\"') + '"' }
  return $s
}

