$path = "E:\project\清泉跨境系统（企业级）\collectors\tiktok-ads\config\stores.config.json"
$raw = Get-Content $path -Raw -Encoding UTF8
$j = $raw | ConvertFrom-Json
# Align with public.shop names from prod/local snapshot
$j.storeNameMap.'Tiktok - KK Seagull' = 'Gardena'
$j.storeNameMap.'TikTok - Pop' = 'TikTok - Pop'
if (-not $j.options.PSObject.Properties['productMaxPages']) {
  $j.options | Add-Member -NotePropertyName productMaxPages -NotePropertyValue 5 -Force
}
if (-not $j.options.PSObject.Properties['productPageWaitMs']) {
  $j.options | Add-Member -NotePropertyName productPageWaitMs -NotePropertyValue 5000 -Force
}
# Add URL blocks if missing
function Ensure-UrlBlock($obj, $name, $default) {
  if (-not $obj.PSObject.Properties[$name]) {
    $block = [pscustomobject]@{ default = $default }
    $obj | Add-Member -NotePropertyName $name -NotePropertyValue $block -Force
  }
}
Ensure-UrlBlock $j 'shopDailyUrl' 'https://seller-uk.tiktok.com/compass/data-overview'
Ensure-UrlBlock $j 'healthUrl' 'https://seller-uk.tiktok.com/shop/health-score'
Ensure-UrlBlock $j 'financeUrl' 'https://seller-uk.tiktok.com/finance/bills'
# Write back via Newtonsoft-less: use JavaScriptSerializer or ConvertTo-Json
$json = $j | ConvertTo-Json -Depth 20
[System.IO.File]::WriteAllText($path, $json, [System.Text.UTF8Encoding]::new($false))
Write-Output 'updated storeNameMap:'
$j.storeNameMap | ConvertTo-Json
Write-Output "productMaxPages=$($j.options.productMaxPages)"

