    $openOut2 = Invoke-Ziniao $openArgs
    Write-Host $openOut2
    Start-Sleep -Milliseconds ([Math]::Max($waitOpenMs, 35000))
    [void](Wait-ZiniaoBridgeReady -MaxSec 50)
    $null = Invoke-Ziniao @('page', 'visit', '--store-id', $sid, '--url', $productUrl, '--wait-until', 'load', '--timeout', '120000')
