input.new_string:
$vis = Invoke-Ziniao @('page', 'visit', '--store-id', $sid, '--url', $productUrl, '--wait-until', 'load', '--timeout', '120000')
  if (Test-ZiniaoBridgeError $vis) {
    Write-Step '  visit hit Bridge error — sleep + retry visit'
    Start-Sleep -Seconds 15
    [void](Wait-ZiniaoBridgeReady -MaxSec 40)
    $vis = Invoke-Ziniao @('page', 'visit', '--store-id', $sid, '--url', $productUrl, '--wait-until', 'load', '--timeout', '120000')
  }
  if ($vis) { Write-Host $vis }
  $afterVisit = 25000
  if ($cfg.options.waitAfterVisitMs) { $afterVisit = [Math]::Max(15000, [int]$cfg.options.waitAfterVisitMs) }
  # product manage 表常异步渲染，固定再等一轮
  Start-Sleep -Milliseconds $afterVisit
  # warm exec: ensure page is not about:blank
  $warmJs = '(function(){return JSON.stringify({ok:true,href:String(location.href||""),rs:document.readyState,tables:document.querySelectorAll("table").length,idHits:(document.body&&document.body.innerText||"").split(/ID\s*[:：]/i).length-1});})();'
  $warm = Invoke-Ziniao @('page', 'exec', '--store-id', $sid, '--script', $warmJs, '--timeout', '30000')
  $warmPayload = Get-ScrapePayload $warm
  $href = ''
  $tables = 0
  $idHits = 0
  if ($warmPayload) {
    if ($warmPayload.href) { $href = [string]$warmPayload.href }
    if ($null -ne $warmPayload.tables) { $tables = [int]$warmPayload.tables }
    if ($null -ne $warmPayload.idHits) { $idHits = [int]$warmPayload.idHits }
  }
  Write-Step ("  warm href={0} tables={1} idHits={2}" -f $(if ($href) { $href } else { '(empty/bridge?)' }), $tables, $idHits)
  $needReopen = $false
  if (Test-ZiniaoBridgeError $warm) { $needReopen = $true }
  if ($href -eq 'about:blank') { $needReopen = $true }
  if ([string]::IsNullOrWhiteSpace($warm) -and [string]::IsNullOrWhiteSpace($href)) { $needReopen = $true }
  if ($needReopen) {
    Write-Step '  warm failed / blank — reopen store once'
    try { $null = Invoke-Ziniao @('store', 'close', '--id', $sid) } catch { }
    Start-Sleep -Seconds 5
    $openOut2 = Invoke-Ziniao $openArgs
    Write-Host $openOut2
    Start-Sleep -Milliseconds ([Math]::Max($waitOpenMs, 40000))
    [void](Wait-ZiniaoBridgeReady -MaxSec 50)
    $null = Invoke-Ziniao @('page', 'visit', '--store-id', $sid, '--url', $productUrl, '--wait-until', 'load', '--timeout', '120000')
    Start-Sleep -Milliseconds $afterVisit
    # second warm
    $warm2 = Invoke-Ziniao @('page', 'exec', '--store-id', $sid, '--script', $warmJs, '--timeout', '30000')
    $wp2 = Get-ScrapePayload $warm2
    if ($wp2 -and $wp2.href) {
      Write-Step ("  warm2 href={0} tables={1}" -f $wp2.href, $(if ($null -ne $wp2.tables) { $wp2.tables } else { '?' }))
    } else {
      Write-Step '  warm2 still empty — will still try scrape'
    }
  } elseif ($tables -eq 0 -and $idHits -le 0) {
    # 页面在 manage 但表未出：再等 + 轻刷新
    Write-Step '  page loaded but no table/ID yet — extra wait 20s'
    Start-Sleep -Seconds 20
  }
}

