    if ($null -ne $warmPayload.tables) { $tables = [int]$warmPayload.tables }
    if ($null -ne $warmPayload.idHits) { $idHits = [int]$warmPayload.idHits }
  }
  Write-Step ("  warm href={0} tables={1} idHits={2}" -f $(if ($href) { $href } else { '(empty/bridge?)' }), $tables, $idHits)
  $needReopen = $false
