    }
  } elseif ($tables -eq 0 -and $idHits -le 0) {
    # 页面在 manage 但表未出：再等 + 轻刷新
    Write-Step '  page loaded but no table/ID yet — extra wait 20s'
    Start-Sleep -Seconds 20
  }
}

