function Open-ProductStore([string]$sid, [string]$productUrl, $cfg, [int]$waitOpenMs) {
  $openArgs = @('store', 'open', '--id', $sid, '--url', $productUrl)
  if ($cfg.options.windowRatio -and $cfg.options.windowRatio -ne 'none') {
    $openArgs += @('--window-ratio', [string]$cfg.options.windowRatio)
  }
  $openOut = Invoke-Ziniao $openArgs
  Write-Host $openOut
  Start-Sleep -Milliseconds $waitOpenMs
  $bridgeWait = 45000
  if ($cfg.options.bridgeRetryWaitMs) { $bridgeWait = [Math]::Max(15000, [int]$cfg.options.bridgeRetryWaitMs) }
  Write-Step ("  wait Bridge ready up to {0}ms..." -f $bridgeWait)
  $ok = Wait-ZiniaoBridgeReady -MaxSec ([Math]::Ceiling($bridgeWait / 1000.0))
  if (-not $ok) { Write-Step '  WARN Bridge not confirmed by doctor — continue anyway' }
  # Prefer load over networkidle: product manage SPA often keeps sockets open → Bridge drop
  Write-Step '  visit product manage (waitUntil=load)...'
  $vis = Invoke-Ziniao @('page', 'visit', '--store-id', $sid, '--url', $productUrl, '--wait-until', 'load', '--timeout', '120000')
  if (Test-ZiniaoBridgeError $vis) {
    Write-Step '  visit hit Bridge error — sleep + retry visit'
    Start-Sleep -Seconds 15
    [void](Wait-ZiniaoBridgeReady -MaxSec 40)
    $vis = Invoke-Ziniao @('page', 'visit', '--store-id', $sid, '--url', $productUrl, '--wait-until', 'load', '--timeout', '120000')
  }
  if ($vis) { Write-Host $vis }
  $afterVisit = 25000
  if ($cfg.options.waitAfterVisitMs) { $afterVisit = [Math]::Max(15000, [int]$cfg.options.waitAfterVisitMs) }
  # product manage 表常异步渲染，固定再等一轮
  Start-Sleep -Milliseconds $afterVisit
  # warm exec: ensure page is not about:blank
  $warmJs = '(function(){return JSON.stringify({ok:true,href:String(location.href||""),rs:document.readyState,tables:document.querySelectorAll("table").length,idHits:(document.body&&document.body.innerText||"").split(/ID\s*[:：]/i).length-1});})();'
  $warm = Invoke-Ziniao @('page', 'exec', '--store-id', $sid, '--script', $warmJs, '--timeout', '30000')
  $warmPayload = Get-ScrapePayload $warm
  $href = ''
  $tables = 0
  $idHits = 0
  if ($warmPayload) {
    if ($warmPayload.href) { $href = [string]$warmPayload.href }
    if ($null -ne $warmPayload.tables) { $tables = [int]$warmPayload.tables }
    if ($null -ne $warmPayload.idHits) { $idHits = [int]$warmPayload.idHits }
  }
  Write-Step ("  warm href={0} tables={1} idHits={2}" -f $(if ($href) { $href } else { '(empty/bridge?)' }), $tables, $idHits)
  $needReopen = $false
  if (Test-ZiniaoBridgeError $warm) { $needReopen = $true }
  if ($href -eq 'about:blank') { $needReopen = $true }
  if ([string]::IsNullOrWhiteSpace($warm) -and [string]::IsNullOrWhiteSpace($href)) { $needReopen = $true }
  if ($needReopen) {
    Write-Step '  warm failed / blank — reopen store once'
    try { $null = Invoke-Ziniao @('store', 'close', '--id', $sid) } catch { }
    Start-Sleep -Seconds 5
    $openOut2 = Invoke-Ziniao $openArgs
    Write-Host $openOut2
    Start-Sleep -Milliseconds ([Math]::Max($waitOpenMs, 40000))
    [void](Wait-ZiniaoBridgeReady -MaxSec 50)
    $null = Invoke-Ziniao @('page', 'visit', '--store-id', $sid, '--url', $productUrl, '--wait-until', 'load', '--timeout', '120000')
    Start-Sleep -Milliseconds $afterVisit
    # second warm
    $warm2 = Invoke-Ziniao @('page', 'exec', '--store-id', $sid, '--script', $warmJs, '--timeout', '30000')
    $wp2 = Get-ScrapePayload $warm2
    if ($wp2 -and $wp2.href) {
      Write-Step ("  warm2 href={0} tables={1}" -f $wp2.href, $(if ($null -ne $wp2.tables) { $wp2.tables } else { '?' }))
    } else {
      Write-Step '  warm2 still empty — will still try scrape'
    }
  } elseif ($tables -eq 0 -and $idHits -le 0) {
    # 页面在 manage 但表未出：再等 + 轻刷新
    Write-Step '  page loaded but no table/ID yet — extra wait 20s'
    Start-Sleep -Seconds 20
  }
}

input.new_string:
function Open-ProductStore([string]$sid, [string]$productUrl, $cfg, [int]$waitOpenMs) {
  # 关键：open 时已带 launchUrl=product/manage。
  # 实探测：page visit 商品页常把 Bridge 打挂（9481 TCP 仍通但 HTTP 失败）；
  # 订单 visit 正常。因此商品链路默认 **跳过 visit**，只靠 open + 长等待 + exec。
  $openArgs = @('store', 'open', '--id', $sid, '--url', $productUrl)
  if ($cfg.options.windowRatio -and $cfg.options.windowRatio -ne 'none') {
    $openArgs += @('--window-ratio', [string]$cfg.options.windowRatio)
  }
  $openOut = Invoke-Ziniao $openArgs
  Write-Host $openOut
  $settle = [Math]::Max($waitOpenMs, 45000)
  Write-Step ("  open done — settle {0}ms (no page visit; product manage Bridge quirk)..." -f $settle)
  Start-Sleep -Milliseconds $settle
  [void](Wait-ZiniaoBridgeReady -MaxSec 30)

  # warm：极简脚本，避免 PS 转义把 JS 弄坏
  $warmJs = 'JSON.stringify({ok:true,href:String(location.href||""),tables:document.querySelectorAll("table").length,tlen:((document.body&&document.body.innerText)||"").length})'
  $warm = Invoke-Ziniao @('page', 'exec', '--store-id', $sid, '--script', $warmJs, '--timeout', '30000')
  $warmPayload = Get-ScrapePayload $warm
  $href = ''
  $tables = 0
  $tlen = 0
  if ($warmPayload) {
    if ($warmPayload.href) { $href = [string]$warmPayload.href }
    if ($null -ne $warmPayload.tables) { $tables = [int]$warmPayload.tables }
    if ($null -ne $warmPayload.tlen) { $tlen = [int]$warmPayload.tlen }
  }
  Write-Step ("  warm href={0} tables={1} tlen={2}" -f $(if ($href) { $href } else { '(empty)' }), $tables, $tlen)

  if (Test-ZiniaoBridgeError $warm -or $href -eq 'about:blank' -or ($tlen -lt 50 -and $tables -eq 0)) {
    Write-Step '  warm weak — extra 25s wait then re-warm (still no visit)'
    Start-Sleep -Seconds 25
    $warm2 = Invoke-Ziniao @('page', 'exec', '--store-id', $sid, '--script', $warmJs, '--timeout', '30000')
    $wp2 = Get-ScrapePayload $warm2
    if ($wp2 -and $wp2.href) {
      Write-Step ("  warm2 href={0} tables={1} tlen={2}" -f $wp2.href, $(if ($null -ne $wp2.tables) { $wp2.tables } else { '?' }), $(if ($null -ne $wp2.tlen) { $wp2.tlen } else { '?' }))
    } else {
      Write-Step '  warm2 empty — will still try scrape'
      if (Test-ZiniaoBridgeError $warm2) {
        Write-Step '  Bridge error on warm2 — close/reopen once'
        try { $null = Invoke-Ziniao @('store', 'close', '--id', $sid) } catch { }
        Start-Sleep -Seconds 5
        Write-Host (Invoke-Ziniao $openArgs)
        Start-Sleep -Milliseconds ([Math]::Max($settle, 50000))
      }
    }
  } elseif ($tables -eq 0 -and $tlen -lt 200) {
    Write-Step '  page thin — wait 20s for SPA render'
    Start-Sleep -Seconds 20
  }
}

