1	# Qingquan center ingest client (Stage A dual-write)
2	# Dot-sourced by run-multi-store.ps1; can also be used alone.
3	#
4	# config.qingquan example:
5	# {
6	#   "enabled": true,
7	#   "baseUrl": "https://qingquan.jmzlai.com",
8	#   "apiKey": "<must match server INGEST_DEFAULT_API_KEY>",
9	#   "source": "tiktok_ads",
10	#   "failOpen": true,
11	#   "timeoutSec": 30
12	# }
13	#
14	# PS 5.1 pitfalls:
15	# - @($hashtable) enumerates KEYS, not a single-element array
16	# - return ,$object[] may still unwrap a single element on assignment
17	# - Generic type literals like List[object] break the parser
18	# Keep items in ArrayList; serialize via JavaScriptSerializer.
