67	function Get-QingquanItemList {
68	  param($Items)
69	  $list = New-Object System.Collections.ArrayList
70	  if ($null -eq $Items) { return $list }
71	
72	  if ($Items -is [System.Collections.ArrayList]) {
73	    foreach ($x in $Items) {
74	      if ($null -ne $x) { [void]$list.Add($x) }
75	    }
76	    return $list
77	  }
78	
79	  # Single Hashtable / Dictionary = one ingest item (do NOT @()-enumerate keys)
80	  if ($Items -is [System.Collections.IDictionary]) {
81	    [void]$list.Add($Items)
82	    return $list
83	  }
84	
85	  if ($Items -is [System.Array]) {
86	    foreach ($x in $Items) {
87	      if ($null -eq $x) { continue }
88	      [void]$list.Add($x)
89	    }
90	    return $list
91	  }
92	
93	  # Other enumerables (but not string)
94	  $isEnum = $false
95	  try {
96	    if (($Items -is [System.Collections.IEnumerable]) -and -not ($Items -is [string])) {
97	      $isEnum = $true
98	    }
99	  } catch { $isEnum = $false }
100	
101	  if ($isEnum) {
102	    foreach ($x in $Items) {
103	      if ($null -ne $x) { [void]$list.Add($x) }
104	    }
105	    return $list
106	  }
107	
108	  [void]$list.Add($Items)
109	  return $list
110	}
