9	#   "source": "tiktok_ads",
10	#   "failOpen": true,
11	#   "timeoutSec": 30
12	# }
13	#
14	# PS 5.1 pitfalls:
15	# - @($hashtable) enumerates KEYS, not a single-element array
16	# - return ,$object[] may still unwrap a single element on assignment
17	# - Generic type literals like List[object] break the parser
18	# Keep items in ArrayList; serialize via JavaScriptSerializer.
