86	    foreach ($x in $Items) {
87	      if ($null -eq $x) { continue }
88	      [void]$list.Add($x)
89	    }
90	    return $list
91	  }
92	
93	  # Other enumerables (but not string)
94	  $isEnum = $false
95	  try {
96	    if (($Items -is [System.Collections.IEnumerable]) -and -not ($Items -is [string])) {
97	      $isEnum = $true
98	    }
