# Install / update Windows Scheduled Task: daily shop-modules (KPI/health/finance)
# 主配置全店 · 紫鸟 Windows 采集机安装（与广告日更同机或另一台均可）
#
# Usage:
#   powershell -ExecutionPolicy Bypass -File .\scripts\install-shop-modules-daily-task.ps1
#   powershell -ExecutionPolicy Bypass -File .\scripts\install-shop-modules-daily-task.ps1 -Time "17:45"
#   powershell -ExecutionPolicy Bypass -File .\scripts\install-shop-modules-daily-task.ps1 -Uninstall
#
# 默认 17:45：错开广告 17:20，避免同时抢紫鸟窗口。

param(
  [string]$Time = '17:45',
  [string]$TaskName = 'TK-Shop-Modules-Daily',
  [switch]$Uninstall
)

$ErrorActionPreference = 'Stop'
$root = Split-Path $PSScriptRoot -Parent
$wrapper = Join-Path $root 'scripts\run-shop-modules-daily.ps1'
$mainConfig = Join-Path $root 'config\stores.config.json'

if ($Uninstall) {
  cmd /c "schtasks /Delete /TN `"$TaskName`" /F >nul 2>&1"
  Write-Host "Removed task: $TaskName"
  exit 0
}

if (-not (Test-Path $wrapper)) {
  throw "Missing $wrapper"
}
if (-not (Test-Path $mainConfig)) {
  throw "Missing main config: $mainConfig (copy from stores.config.example.json)"
}

if ($Time -notmatch '^(\d{1,2}):(\d{2})$') {
  throw "Invalid -Time $Time, use HH:mm e.g. 17:45"
}
$hh = [int]$Matches[1]
$mm = [int]$Matches[2]
if ($hh -gt 23 -or $mm -gt 59) { throw "Invalid time $Time" }
$st = '{0:D2}:{1:D2}' -f $hh, $mm

# 轻量自检：主配置应无全店 filter，不应长期绑死单店 include
try {
  $cfg = Get-Content $mainConfig -Raw -Encoding UTF8 | ConvertFrom-Json
  $inc = @()
  if ($cfg.filter -and $cfg.filter.includeStoreIds) {
    $inc = @($cfg.filter.includeStoreIds | Where-Object { $_ -and [string]$_ -ne '' })
  }
  if ($inc.Count -gt 0) {
    Write-Host "WARN: stores.config.json filter.includeStoreIds 非空 = [$($inc -join ',')] — 日更将只跑这些店，不是全店。"
