    Write-Host "WARN: options.dryRun=true — 包装脚本会强制 -DryRun false，配置里 dryRun 不影响本任务实写。"
  }
  if (-not ($cfg.qingquan -and $cfg.qingquan.enabled)) {
    Write-Host "WARN: qingquan.enabled 未开 — 抓到也不会上报中心。"
  }
