Write-Host "  2) Ziniao client running + logged in (ziniao-cli doctor)"
Write-Host "  3) Bridge 通 (127.0.0.1:9481)"
Write-Host "  4) stores.config.json: qingquan.enabled + apiKey 对生产"
Write-Host "  5) 店铺已绑 IP（requireIp=true 会跳过未绑店）"
Write-Host ""
Write-Host "Manual test:"
Write-Host "  schtasks /Run /TN $TaskName"
Write-Host "  # 或前台:"
Write-Host "  powershell -ExecutionPolicy Bypass -File .\scripts\run-shop-modules.ps1 -ListOnly"
Write-Host "  powershell -ExecutionPolicy Bypass -File .\scripts\run-shop-modules-daily.ps1"
Write-Host "  Get-ChildItem logs\shop-modules-daily-*.log | Sort-Object LastWriteTime -Descending | Select-Object -First 1 | ForEach-Object { Get-Content `$_.FullName -Tail 60 }"
