    if ($wp2 -and $wp2.href) {
      Write-Step ("  warm2 href={0} tables={1} tlen={2}" -f $wp2.href, $(if ($null -ne $wp2.tables) { $wp2.tables } else { '?' }), $(if ($null -ne $wp2.tlen) { $wp2.tlen } else { '?' }))
    } else {
      Write-Step '  warm2 empty — will still try scrape'
      if (Test-ZiniaoBridgeError $warm2) {
        Write-Step '  Bridge error on warm2 — close/reopen once'
        try { $null = Invoke-Ziniao @('store', 'close', '--id', $sid) } catch { }
        Start-Sleep -Seconds 5
        Write-Host (Invoke-Ziniao $openArgs)
        Start-Sleep -Milliseconds ([Math]::Max($settle, 50000))
      }
    }
