input.command:
Set-Location "E:\project\清泉跨境系统（企业级）\collectors\tiktok-ads"
# Retry failed ingests from latest debug via curl
$cfg = Get-Content .\config\stores.config.json -Raw -Encoding UTF8 | ConvertFrom-Json
$base = $cfg.qingquan.baseUrl.TrimEnd('/'); $apiKey = $cfg.qingquan.apiKey
$dir = 'C:\Users\Administrator\AppData\Local\Temp\qq_ingest'; New-Item -ItemType Directory -Force -Path $dir | Out-Null
$collected = (Get-Date).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ss+00:00')
$biz = '2026-08-02'

function Post($source, $storeId, $name, $payloadHash) {
  $body = @{ items = @(@{ platform='tiktok'; shop_id=$storeId; shop_name=$name; biz_date=$biz; collected_at=$collected; idempotency_key=("${source}:${storeId}:${biz}"); payload=$payloadHash; evidence=@{source_url=$payloadHash.source_url} }) }
  $json = $body | ConvertTo-Json -Depth 14 -Compress
  $tmp = Join-Path $dir "$source-$storeId.json"; $out = Join-Path $dir "$source-$storeId-out.json"
  [IO.File]::WriteAllText($tmp, $json, [Text.UTF8Encoding]::new($false))
  $code = & curl.exe -sS -X POST "$base/api/v1/ingest/$source" -H "Content-Type: application/json; charset=utf-8" -H "X-Api-Key: $apiKey" --data-binary "@$tmp" -o $out -w "%{http_code}" --max-time 60 --retry 2
  Write-Output "$source $name http=$code $(Get-Content $out -Raw)"
}

# Deal shop_daily from summary debug
$dealShop = Get-ChildItem logs\shop_daily-debug-27501502216807-*.json | Sort-Object LastWriteTime -Descending | Select-Object -First 1
$gardHealth = Get-ChildItem logs\health_daily-debug-27328767468273-*.json | Sort-Object LastWriteTime -Descending | Select-Object -First 1
if ($dealShop) {
  $j = Get-Content $dealShop.FullName -Raw -Encoding UTF8 | ConvertFrom-Json
  $p = $j.payload
  Post 'tiktok_shop_daily' $j.storeId $j.displayName @{ gmv=$p.gmv; orders_cnt=$p.ordersCnt; buyers_cnt=$p.buyersCnt; refund_amount=$p.refundAmount; currency=$p.currency; source_url=$p.url; scrape_raw=$p.raw }
}
if ($gardHealth) {
  $j = Get-Content $gardHealth.FullName -Raw -Encoding UTF8 | ConvertFrom-Json
  $p = $j.payload
  Post 'tiktok_health_daily' $j.storeId $j.displayName @{ health_score=$p.healthScore; late_dispatch_rate=$p.lateDispatchRate; negative_feedback_rate=$p.negativeFeedbackRate; status_label=$p.statusLabel; source_url=$p.url; scrape_raw=$p.raw }
}

